import test from "node:test";
import assert from "node:assert/strict";
import {planner, apply} from "./replay.mjs";
import {readCatalog} from "./common/limits.mjs";

const date = "2025-04-02";
const book = (id, units, extra = {}) => ({service:"studio", action:"book", id,
  tenant:"orchid", day:date, units, ...extra});

test("Studio admission accounts per tenant/day and preserves ID semantics", () => {
  const dispatch = planner(readCatalog());
  assert.deepEqual(dispatch(book("first", 7)), {status:"booked", id:"first", remaining:1});
  assert.deepEqual(dispatch(book("too-big", 2)), {status:"full", id:"too-big", remaining:1});
  assert.equal(dispatch(book("last", 1)).status, "booked");
  assert.equal(dispatch(book("first", 7)).status, "replay");
  assert.equal(dispatch(book("first", 6)).status, "conflict");
  assert.equal(dispatch(book("iris", 5, {tenant:"iris"})).status, "booked");
  assert.equal(dispatch(book("iris-full", 1, {tenant:"iris"})).status, "full");
  assert.equal(dispatch(book("other-day", 8, {day:"2025-04-03"})).status, "booked");
  assert.equal(dispatch({service:"studio", action:"cancel", id:"first"}).status, "cancelled");
  assert.equal(dispatch(book("first", 7)).status, "cancelled");
  assert.deepEqual(dispatch(book("too-big", 2)), {status:"booked", id:"too-big", remaining:5});
  assert.deepEqual(dispatch({service:"studio", action:"usage", tenant:"orchid", day:date}), {units:3});
});

test("renewals inherit the source tenant and use Studio admission", () => {
  const dispatch = planner(readCatalog());
  dispatch(book("source", 8, {day:"2025-03-02"}));
  const next = {service:"studio", action:"renew", previous:"source", id:"next", day:date,
    tenant:"iris"};
  assert.deepEqual(dispatch(next), {status:"booked", id:"next", remaining:0});
  assert.equal(dispatch(next).status, "replay");
  assert.equal(dispatch({...next, units:7}).status, "conflict");
  assert.equal(dispatch({...next, id:"excess", units:1}).status, "full");
  assert.equal(dispatch({service:"studio", action:"lookup", id:"next"}).tenant, "orchid");
  dispatch({service:"studio", action:"cancel", id:"next"});
  assert.equal(dispatch(next).status, "cancelled");
  assert.equal(dispatch({...next, previous:"next", id:"missing"}).status, "missing");
  assert.equal(apply(dispatch, {...next, units:0}).status, "invalid");
});

test("imports count toward Studio usage and lower quotas are enforced", () => {
  const dispatch = planner({default:5, studios:new Map([["orchid", 3]])});
  assert.equal(dispatch(book("lower", 4)).status, "full");
  assert.equal(dispatch({...book("backfill", 7), action:"import"}).status, "imported");
  assert.deepEqual(dispatch(book("full", 1)), {status:"full", id:"full", remaining:0});
  assert.equal(dispatch(book("backfill", 7)).status, "replay");
  dispatch({service:"studio", action:"cancel", id:"backfill"});
  assert.equal(dispatch(book("new", 3)).status, "booked");
});

test("unlisted Studio tenants and Archive keep the catalog default on both paths", () => {
  const dispatch = planner(readCatalog());
  for (const extra of [{tenant:"iris"}, {service:"archive"}]) {
    assert.equal(dispatch(book("large", 6, extra)).status, "full");
    dispatch(book("source", 5, {...extra, day:"2025-03-02"}));
    const next = {action:"renew", service:extra.service ?? "studio", previous:"source",
      id:"next", day:date, units:6};
    assert.equal(dispatch(next).status, "full");
    assert.deepEqual(dispatch({...next, units:5}), {status:"booked", id:"next", remaining:0});
  }
});
